import Image from "next/image";

export default function Hero() {
  const flower =
    "https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199688/homeheroflower_l0owlr.webp";
  const person =
    "https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199689/person_isbwyu.webp";
  const splash =
    "https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199690/splash_z7aa5q.png";

  return (
    <section className="group relative flex h-[90vh] w-full items-center justify-center overflow-hidden bg-white">

      {/* 🌸 Top Left */}
      <Image
        src={flower}
        alt="Decorative flower top left"
        width={600}
        height={600}
        priority
        className="
        absolute top-0 left-0

        w-[18rem] lg:w-[35rem]

        -mt-[40px] -ml-[30px]
        lg:-mt-[120px] lg:-ml-[40px]

        translate-x-[30%] translate-y-[30%]

        group-hover:translate-x-0 group-hover:translate-y-0
        transition-transform duration-700 ease-in-out
        "
      />

      {/* 🌸 Top Right */}
      <Image
        src={flower}
        alt="Decorative flower top right"
        width={600}
        height={600}
        priority
        className="
        absolute top-0 right-0

        w-[18rem] lg:w-[35rem]

        -mt-[30px] -mr-[30px]
        lg:-mt-[110px] lg:-mr-[50px]

        -translate-x-[30%] translate-y-[30%]

        group-hover:translate-x-0 group-hover:translate-y-0
        transition-transform duration-700 ease-in-out
        "
      />

      {/* 🌸 Bottom Left */}
      <Image
        src={flower}
        alt="Decorative flower bottom left"
        width={600}
        height={600}
        className="
        absolute bottom-0 left-0

        w-[18rem] lg:w-[35rem]

        -mb-[50px] -ml-[40px]
        lg:-mb-[100px] lg:-ml-[100px]

        scale-x-[-1]

        translate-x-[30%] -translate-y-[30%]

        group-hover:translate-x-0 group-hover:translate-y-0
        transition-transform duration-700 ease-in-out
        "
      />

      {/* 🌸 Bottom Right */}
      <Image
        src={flower}
        alt="Decorative flower bottom right"
        width={600}
        height={600}
        className="
        absolute bottom-0 right-0

        w-[18rem] lg:w-[35rem]

        -mb-[50px] -mr-[40px]
        lg:-mb-[100px] lg:-mr-[60px]

        scale-x-[-1]

        -translate-x-[30%] -translate-y-[30%]

        group-hover:translate-x-0 group-hover:translate-y-0
        transition-transform duration-700 ease-in-out
        "
      />

      {/* 👤 Person */}
      <div
        className="
        absolute top-[20px] z-10 flex items-center justify-center

        w-[23rem]
        lg:w-[23rem]
        "
        style={{
          backgroundImage: `url(${splash})`,
          backgroundRepeat: "no-repeat",
          backgroundPosition: "center",
          backgroundSize: "100%",
        }}
      >
        <Image
          src={person}
          alt="Main person illustration"
          width={400}
          height={400}
          priority
          className="w-full h-auto"
        />
      </div>
    </section>
  );
}